//! Standard-library-only research baseline for 15-60 minute crypto signals.
//!
//! This file implements the model core only:
//! - multinomial logistic regression: P(WIN / NEUTRAL / LOSS)
//! - Ridge-style linear regression: expected net return in basis points
//! - long/short candidate comparison and a simple entry policy
//!
//! Market-data ingestion, feature calculations, triple-barrier simulation,
//! exchange order placement, and portfolio accounting are intentionally
//! separate. TrainingSample rows must be generated by that simulator.
//!
//! ИЗМЕНЕНИЯ относительно исходной версии:
//!   1. classify_outcome: допуск LABEL_EPS_BPS при сравнении с edge_buffer
//!      (иначе касание TP, стоящего ровно на cost + buffer, давало случайную метку).
//!   2. load_from_file принимает expected_features: схема признаков больше не
//!      зашита на 23 (V1), можно загружать и модель V2 (23 + потоковые признаки).

const CLASS_COUNT: usize = 3;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Side {
    Long,
    Short,
}

impl Side {
    fn sign(self) -> f64 {
        match self {
            Side::Long => 1.0,
            Side::Short => -1.0,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Outcome {
    Win,
    Neutral,
    Loss,
}

impl Outcome {
    fn index(self) -> usize {
        match self {
            Outcome::Win => 0,
            Outcome::Neutral => 1,
            Outcome::Loss => 2,
        }
    }
}

/// One hypothetical trade after its future path has been simulated.
///
/// `features` contains only information available at decision time t.
/// Create one row for LONG and one for SHORT at every training timestamp.
/// `net_return_bps` is after fees, spread, slippage, impact, and funding.
#[derive(Clone, Debug)]
pub struct TrainingSample {
    /// For `FeaturesV1`, use `FeaturesV1::to_vec()` in the declared field order.
    pub features: Vec<f64>,
    pub side: Side,
    pub outcome: Outcome,
    pub net_return_bps: f64,
}

