/// Допуск (в б.п.) на погрешность вычислений с плавающей точкой при сравнении с порогом.
/// Нужен, потому что TP стоит ровно на cost + edge_buffer, и net получается
/// edge_buffer ± ~1e-14: строгое ">" давало случайные метки Win/Neutral.
const LABEL_EPS_BPS: f64 = 1e-6;

/// Convert a simulated trade into the classifier target.
///
/// `gross_mid_return_bps` is mid-to-mid return (before execution costs).
/// `cost_rt_bps` is the estimated round-trip cost for the reference notional.
pub fn classify_outcome(
    side: Side,
    gross_mid_return_bps: f64,
    net_return_bps: f64,
    cost_rt_bps: f64,
    edge_buffer_bps: f64,
) -> Outcome {
    // Доходность в направлении сделки: gross_side = sign(side) * gross_mid
    // (Long -> +gross_mid, Short -> -gross_mid).
    let gross_side_return_bps = side.sign() * gross_mid_return_bps;

    // Win: net >= edge_buffer (с допуском на float, иначе касание TP даёт случайную метку).
    if net_return_bps >= edge_buffer_bps - LABEL_EPS_BPS {
        Outcome::Win
    // Loss: net хуже -edge_buffer И рынок ушёл против нас сильнее, чем стоят издержки.
    } else if net_return_bps < -edge_buffer_bps && gross_side_return_bps < -cost_rt_bps {
        Outcome::Loss
    } else {
        // Includes moves too small to clear round-trip costs.
        Outcome::Neutral
    }
}

#[derive(Clone, Debug)]
pub struct ModelConfig {
    pub epochs: usize,
    pub learning_rate: f64,
    pub classifier_l2: f64,
    pub return_l2: f64,
}

impl Default for ModelConfig {
    fn default() -> Self {
        Self {
            epochs: 2_000,
            // This is a base rate; each optimizer divides it by encoded width.
            learning_rate: 0.5,
            classifier_l2: 0.01,
            return_l2: 1.0,
        }
    }
}

#[derive(Clone, Debug)]
struct FeatureScaler {
    mean: Vec<f64>,
    scale: Vec<f64>,
}

impl FeatureScaler {
    fn fit(samples: &[TrainingSample]) -> Result<Self, String> {
        if samples.is_empty() {
            return Err("training set is empty".to_string());
        }
        let width = samples[0].features.len();
        if width == 0 {
            return Err("feature vector is empty".to_string());
        }
        if samples.iter().any(|row| row.features.len() != width) {
            return Err("feature vectors have different lengths".to_string());
        }

        let n = samples.len() as f64;
        let mut mean = vec![0.0; width];
        for row in samples {
            for (j, value) in row.features.iter().enumerate() {
                if !value.is_finite() {
                    return Err("features must be finite; impute before fitting".to_string());
                }
                mean[j] += value;
            }
        }
        for value in &mut mean {
            *value /= n;
        }

        let mut variance = vec![0.0; width];
        for row in samples {
            for j in 0..width {
                let delta = row.features[j] - mean[j];
                variance[j] += delta * delta;
            }
        }
        let scale = variance
            .into_iter()
            .map(|v| {
                let std = (v / n).sqrt();
                if std < 1e-12 { 1.0 } else { std }
            })
            .collect();

        Ok(Self { mean, scale })
    }

    fn transform(&self, features: &[f64]) -> Result<Vec<f64>, String> {
        if features.len() != self.mean.len() {
            return Err("feature count does not match fitted scaler".to_string());
        }
        let mut out = Vec::with_capacity(features.len());
        for j in 0..features.len() {
            if !features[j].is_finite() {
                return Err("features must be finite at inference".to_string());
            }
            out.push((features[j] - self.mean[j]) / self.scale[j]);
        }
        Ok(out)
    }
}

/// Add side information and side-feature interactions.
///
/// The interactions let the shared model learn different feature effects
/// for long and short candidates.
fn side_interactions(scaled: &[f64], side: Side) -> Vec<f64> {
    let s = side.sign();
    let mut phi = Vec::with_capacity(2 + scaled.len() * 2);
    phi.push(1.0); // unregularized intercept
    phi.extend_from_slice(scaled);
    phi.push(s);
    phi.extend(scaled.iter().map(|x| s * x));
    phi
}

#[derive(Clone, Debug)]
struct MultinomialLogit {
    // weights[feature_index][class_index]
    weights: Vec<[f64; CLASS_COUNT]>,
}

impl MultinomialLogit {
    fn new(feature_count: usize) -> Self {
        Self {
            weights: vec![[0.0; CLASS_COUNT]; feature_count],
        }
    }

    fn logits(&self, phi: &[f64]) -> [f64; CLASS_COUNT] {
        let mut result = [0.0; CLASS_COUNT];
        for j in 0..self.weights.len() {
            for k in 0..CLASS_COUNT {
                result[k] += self.weights[j][k] * phi[j];
            }
        }
        result
    }

    fn fit(
        &mut self,
        rows: &[Vec<f64>],
        labels: &[Outcome],
        epochs: usize,
        learning_rate: f64,
        l2: f64,
    ) -> Result<(), String> {
        validate_matrix(rows, labels.len(), self.weights.len())?;
        if rows.is_empty() {
            return Err("classifier training set is empty".to_string());
        }
        let n = rows.len() as f64;
        let step_size = learning_rate / self.weights.len().max(1) as f64;

        for _ in 0..epochs {
            let mut grad = vec![[0.0; CLASS_COUNT]; self.weights.len()];
            for (phi, label) in rows.iter().zip(labels.iter()) {
                let probabilities = softmax(self.logits(phi));
                for k in 0..CLASS_COUNT {
                    let target = if label.index() == k { 1.0 } else { 0.0 };
                    let error = probabilities[k] - target;
                    for j in 0..phi.len() {
                        grad[j][k] += error * phi[j] / n;
                    }
                }
            }

            for j in 0..self.weights.len() {
                for k in 0..CLASS_COUNT {
                    // Do not regularize the intercept.
                    if j > 0 {
                        grad[j][k] += l2 * self.weights[j][k];
                    }
                    self.weights[j][k] -= step_size * grad[j][k];
                }
            }
        }
        Ok(())
    }
}

/// Linear Ridge-style predictor trained with full-batch gradient descent.
#[derive(Clone, Debug)]
struct ReturnRegressor {
    weights: Vec<f64>,
}

impl ReturnRegressor {
    fn new(feature_count: usize) -> Self {
        Self {
            weights: vec![0.0; feature_count],
        }
    }

    fn predict(&self, phi: &[f64]) -> f64 {
        self.weights
            .iter()
            .zip(phi.iter())
            .map(|(w, x)| w * x)
            .sum()
    }

    fn fit(
        &mut self,
        rows: &[Vec<f64>],
        targets_bps: &[f64],
        epochs: usize,
        learning_rate: f64,
        l2: f64,
    ) -> Result<(), String> {
        validate_matrix(rows, targets_bps.len(), self.weights.len())?;
        if rows.is_empty() {
            return Err("return-regression training set is empty".to_string());
        }
        if targets_bps.iter().any(|y| !y.is_finite()) {
            return Err("return targets must be finite".to_string());
        }
        let n = rows.len() as f64;
        let step_size = learning_rate / self.weights.len().max(1) as f64;

        for _ in 0..epochs {
            let mut grad = vec![0.0; self.weights.len()];
            for (phi, target) in rows.iter().zip(targets_bps.iter()) {
                let error = self.predict(phi) - target;
                for j in 0..phi.len() {
                    grad[j] += 2.0 * error * phi[j] / n;
                }
            }
            for j in 0..self.weights.len() {
                if j > 0 {
                    grad[j] += 2.0 * l2 * self.weights[j];
                }
                self.weights[j] -= step_size * grad[j];
            }
        }
        Ok(())
    }
}

fn validate_matrix(rows: &[Vec<f64>], target_len: usize, width: usize) -> Result<(), String> {
    if rows.len() != target_len {
        return Err("number of feature rows and targets differs".to_string());
    }
    if rows.iter().any(|row| row.len() != width) {
        return Err("encoded feature width is inconsistent".to_string());
    }
    if rows.iter().flatten().any(|x| !x.is_finite()) {
        return Err("encoded features must be finite".to_string());
    }
    Ok(())
}

fn softmax(logits: [f64; CLASS_COUNT]) -> [f64; CLASS_COUNT] {
    let max_logit = logits[0].max(logits[1]).max(logits[2]);
    let e = [
        (logits[0] - max_logit).exp(),
        (logits[1] - max_logit).exp(),
        (logits[2] - max_logit).exp(),
    ];
    let sum = e[0] + e[1] + e[2];
    [e[0] / sum, e[1] / sum, e[2] / sum]
}

/// One-parameter temperature calibration, fitted on a later chronological
/// calibration slice that was not used to fit the classifier.
#[derive(Clone, Copy, Debug)]
pub struct TemperatureScaler {
    temperature: f64,
}

impl TemperatureScaler {
    pub fn identity() -> Self {
        Self { temperature: 1.0 }
    }

    pub fn fit(logits: &[[f64; CLASS_COUNT]], labels: &[Outcome]) -> Result<Self, String> {
        if logits.is_empty() || logits.len() != labels.len() {
            return Err("calibration rows and labels must be non-empty and aligned".to_string());
        }

        let loss_at = |log_temperature: f64| -> f64 {
            let temperature = log_temperature.exp();
            let mut loss = 0.0;
            for (row, label) in logits.iter().zip(labels.iter()) {
                let scaled = [
                    row[0] / temperature,
                    row[1] / temperature,
                    row[2] / temperature,
                ];
                let p = softmax(scaled)[label.index()].max(1e-15);
                loss -= p.ln();
            }
            loss / logits.len() as f64
        };

        // Golden-section search for log(T) in [ln(0.1), ln(10)].
        let mut lo = 0.1_f64.ln();
        let mut hi = 10.0_f64.ln();
        let ratio = 0.618_033_988_749_894_9;
        let mut left = hi - ratio * (hi - lo);
        let mut right = lo + ratio * (hi - lo);
        for _ in 0..100 {
            if loss_at(left) < loss_at(right) {
                hi = right;
                right = left;
                left = hi - ratio * (hi - lo);
            } else {
                lo = left;
                left = right;
                right = lo + ratio * (hi - lo);
            }
        }
        Ok(Self {
            temperature: ((lo + hi) * 0.5).exp(),
        })
    }

    fn apply(&self, logits: [f64; CLASS_COUNT]) -> [f64; CLASS_COUNT] {
        softmax([
            logits[0] / self.temperature,
            logits[1] / self.temperature,
            logits[2] / self.temperature,
        ])
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Prediction {
    pub p_win: f64,
    pub p_neutral: f64,
    pub p_loss: f64,
    /// Expected net return, in basis points, for the reference notional.
    pub expected_net_return_bps: f64,
}

#[derive(Clone, Debug)]
pub struct IntradayModel {
    scaler: FeatureScaler,
    classifier: MultinomialLogit,
    return_model: ReturnRegressor,
    temperature: TemperatureScaler,
    feature_count: usize,
}

impl IntradayModel {
    /// Save the fitted scaler, classifier, return regressor and calibration.
    /// Text format is versioned and uses only the standard library.
    pub fn save_to_file(&self, path: &str) -> Result<(), String> {
        use std::io::Write;
        let mut f = std::fs::File::create(path).map_err(|e| e.to_string())?;
        writeln!(
            f,
            "INTRADAY_MODEL_V1\n{}\n{}",
            self.feature_count, self.temperature.temperature
        )
        .map_err(|e| e.to_string())?;
        for v in &self.scaler.mean {
            writeln!(f, "{v:.17}").map_err(|e| e.to_string())?;
        }
        for v in &self.scaler.scale {
            writeln!(f, "{v:.17}").map_err(|e| e.to_string())?;
        }
        for w in &self.classifier.weights {
            writeln!(f, "{:.17} {:.17} {:.17}", w[0], w[1], w[2]).map_err(|e| e.to_string())?;
        }
        for v in &self.return_model.weights {
            writeln!(f, "{v:.17}").map_err(|e| e.to_string())?;
        }
        Ok(())
    }

    /// Загружает модель, ранее сохранённую `save_to_file`.
    ///
    /// `expected_features` - ожидаемое число признаков схемы: 23 для V1,
    /// 31 для V2 (V1 + 8 потоковых признаков из aggTrades). Проверка не даёт
    /// загрузить модель другой схемы и получить молча неверные предсказания.
    pub fn load_from_file(path: &str, expected_features: usize) -> Result<Self, String> {
        let content = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
        let mut it = content.split_whitespace();
        if it.next() != Some("INTRADAY_MODEL_V1") {
            return Err("unsupported model file version".into());
        }
        let next_f64 = |it: &mut std::str::SplitWhitespace<'_>| -> Result<f64, String> {
            let x = it
                .next()
                .ok_or("truncated model file")?
                .parse::<f64>()
                .map_err(|_| "invalid number in model file")?;
            if !x.is_finite() {
                return Err("non-finite model parameter".into());
            }
            Ok(x)
        };
        let n = it
            .next()
            .ok_or("missing feature count")?
            .parse::<usize>()
            .map_err(|_| "invalid feature count")?;
        if n != expected_features {
            return Err(format!(
                "model feature schema mismatch: file has {n} features, expected {expected_features}"
            ));
        }
        let temperature = next_f64(&mut it)?;
        if temperature <= 0.0 {
            return Err("invalid temperature".into());
        }
        let mut mean = Vec::with_capacity(n);
        for _ in 0..n {
            mean.push(next_f64(&mut it)?);
        }
        let mut scale = Vec::with_capacity(n);
        for _ in 0..n {
            let x = next_f64(&mut it)?;
            if x <= 0.0 {
                return Err("invalid feature scale".into());
            }
            scale.push(x);
        }
        let width = 2 + 2 * n;
        let mut weights = Vec::with_capacity(width);
        for _ in 0..width {
            weights.push([next_f64(&mut it)?, next_f64(&mut it)?, next_f64(&mut it)?]);
        }
        let mut return_weights = Vec::with_capacity(width);
        for _ in 0..width {
            return_weights.push(next_f64(&mut it)?);
        }
        if it.next().is_some() {
            return Err("unexpected extra model data".into());
        }
        Ok(Self {
            scaler: FeatureScaler { mean, scale },
            classifier: MultinomialLogit { weights },
            return_model: ReturnRegressor {
                weights: return_weights,
            },
            temperature: TemperatureScaler { temperature },
            feature_count: n,
        })
    }

    /// Fit using training rows only. Calibrate later with `fit_calibrator`.
    pub fn fit(train: &[TrainingSample], config: &ModelConfig) -> Result<Self, String> {
        if train.is_empty() {
            return Err("training set is empty".to_string());
        }
        let feature_count = train[0].features.len();
        let scaler = FeatureScaler::fit(train)?;
        let mut encoded = Vec::with_capacity(train.len());
        let mut classes = Vec::with_capacity(train.len());
        let mut returns = Vec::with_capacity(train.len());

        for row in train {
            if row.features.len() != feature_count {
                return Err("training feature count is inconsistent".to_string());
            }
            let scaled = scaler.transform(&row.features)?;
            encoded.push(side_interactions(&scaled, row.side));
            classes.push(row.outcome);
            returns.push(row.net_return_bps);
        }

        let encoded_width = encoded[0].len();
        let mut classifier = MultinomialLogit::new(encoded_width);
        classifier.fit(
            &encoded,
            &classes,
            config.epochs,
            config.learning_rate,
            config.classifier_l2,
        )?;

        let mut return_model = ReturnRegressor::new(encoded_width);
        return_model.fit(
            &encoded,
            &returns,
            config.epochs,
            config.learning_rate,
            config.return_l2,
        )?;

        Ok(Self {
            scaler,
            classifier,
            return_model,
            temperature: TemperatureScaler::identity(),
            feature_count,
        })
    }

    /// Fit temperature on a chronological calibration slice inside train.
    /// These rows must be later than, and disjoint from, rows passed to `fit`.
    /// Do not pass the final test period here.
    pub fn fit_calibrator(&mut self, calibration: &[TrainingSample]) -> Result<(), String> {
        if calibration.is_empty() {
            return Err("calibration set is empty".to_string());
        }
        let mut logits = Vec::with_capacity(calibration.len());
        let mut labels = Vec::with_capacity(calibration.len());
        for row in calibration {
            if row.features.len() != self.feature_count {
                return Err("calibration feature count differs from training".to_string());
            }
            let scaled = self.scaler.transform(&row.features)?;
            let phi = side_interactions(&scaled, row.side);
            logits.push(self.classifier.logits(&phi));
            labels.push(row.outcome);
        }
        self.temperature = TemperatureScaler::fit(&logits, &labels)?;
        Ok(())
    }

    pub fn predict(&self, features: &[f64], side: Side) -> Result<Prediction, String> {
        let scaled = self.scaler.transform(features)?;
        let phi = side_interactions(&scaled, side);
        let probabilities = self.temperature.apply(self.classifier.logits(&phi));
        Ok(Prediction {
            p_win: probabilities[Outcome::Win.index()],
            p_neutral: probabilities[Outcome::Neutral.index()],
            p_loss: probabilities[Outcome::Loss.index()],
            expected_net_return_bps: self.return_model.predict(&phi),
        })
    }

    pub fn predict_v1(&self, features: FeaturesV1, side: Side) -> Result<Prediction, String> {
        self.predict(&features.to_vec(), side)
    }

    pub fn predict_v2(&self, features: FeaturesV1, side: Side) -> Result<Prediction, String> {
        self.predict(&features.to_vec(), side)
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Policy {
    pub min_win_probability: f64,
    pub min_expected_net_return_bps: f64,
}

#[derive(Clone, Copy, Debug)]
pub enum Signal {
    Flat,
    Candidate { side: Side, prediction: Prediction },
}

/// Choose the better hypothetical side. This creates a signal only;
/// exchange order placement and risk checks belong in the execution layer.
pub fn choose_signal(
    model: &IntradayModel,
    features: &[f64],
    policy: Policy,
) -> Result<Signal, String> {
    let long = model.predict(features, Side::Long)?;
    let short = model.predict(features, Side::Short)?;
    let long_passes = long.expected_net_return_bps >= policy.min_expected_net_return_bps
        && long.p_win >= policy.min_win_probability;
    let short_passes = short.expected_net_return_bps >= policy.min_expected_net_return_bps
        && short.p_win >= policy.min_win_probability;

    // First apply the gates to each side, then choose the best eligible one.
    // Otherwise a high-EV side that fails P_WIN could incorrectly hide an
    // eligible trade in the opposite direction.
    match (long_passes, short_passes) {
        (false, false) => Ok(Signal::Flat),
        (true, false) => Ok(Signal::Candidate {
            side: Side::Long,
            prediction: long,
        }),
        (false, true) => Ok(Signal::Candidate {
            side: Side::Short,
            prediction: short,
        }),
        (true, true) => {
            if long.expected_net_return_bps >= short.expected_net_return_bps {
                Ok(Signal::Candidate {
                    side: Side::Long,
                    prediction: long,
                })
            } else {
                Ok(Signal::Candidate {
                    side: Side::Short,
                    prediction: short,
                })
            }
        }
    }
}

pub fn choose_signal_v1(
    model: &IntradayModel,
    features: FeaturesV1,
    policy: Policy,
) -> Result<Signal, String> {
    choose_signal(model, &features.to_vec(), policy)
}

